use std::fs;
use std::path::Path;

use anyhow::Result;

use super::registry::{
    FrontendOperationSpec, agent_templates, builtin_providers, graph_attr_constants,
    graph_metric_constants, operation_specs, provider_protocols,
};

pub fn render_typescript_frontend_contract() -> String {
    let mut buf = String::new();
    buf.push_str(
        "// AUTO-GENERATED by apxm codegen typescript-frontend; DO NOT EDIT.\n\n",
    );
    for operation in apxm_ais::SemanticOpKind::all() {
        buf.push_str(&format!(
            "export const SEMANTIC_{} = {} as const;\n",
            constant_name(operation.wire()),
            ts_string(operation.wire())
        ));
    }
    buf.push('\n');
    buf.push_str(&format!(
        "export const INTERNAL_STRUCTURAL_REGION = {} as const;\n\n",
        ts_string(apxm_ais::StructuralOpKind::Region.wire())
    ));
    for kind in apxm_ais::StructuralOpKind::all()
        .into_iter()
        .filter(|kind| {
            !matches!(
                kind,
                apxm_ais::StructuralOpKind::Function
                    | apxm_ais::StructuralOpKind::Region
                    | apxm_ais::StructuralOpKind::Block
                    | apxm_ais::StructuralOpKind::Value
            )
        })
    {
        buf.push_str(&format!(
            "export const STRUCTURAL_{} = {} as const;\n",
            constant_name(kind.wire()),
            ts_string(kind.wire())
        ));
    }
    buf.push_str(
        "\nexport const SEMANTIC_OPERATION_KINDS = [\n\
         \x20 SEMANTIC_MODEL_CALL,\n\
         \x20 SEMANTIC_CAPABILITY_INVOKE,\n\
         \x20 SEMANTIC_PROGRAM_NEW,\n\
         \x20 SEMANTIC_PROGRAM_INVOKE,\n\
         \x20 SEMANTIC_AWAIT_EVENT,\n\
         ] as const;\n\n",
    );
    buf.push_str(
        "export const AUTHOR_STRUCTURAL_KINDS = [\n\
         \x20 STRUCTURAL_BRANCH,\n\
         \x20 STRUCTURAL_SWITCH,\n\
         \x20 STRUCTURAL_AIS_LOOP,\n\
         \x20 STRUCTURAL_PARALLEL_JOIN,\n\
         \x20 STRUCTURAL_TRY,\n\
         \x20 STRUCTURAL_THROW,\n\
         \x20 STRUCTURAL_CATCH,\n\
         \x20 STRUCTURAL_RETURN,\n\
         \x20 STRUCTURAL_YIELD,\n\
         ] as const;\n",
    );
    buf
}

pub fn render_typescript_frontend_files() -> Vec<(&'static str, String)> {
    vec![
        (
            "frontend-contract.ts",
            render_typescript_frontend_contract(),
        ),
        ("runtime-evidence.ts", render_runtime_evidence_typescript()),
    ]
}

fn render_runtime_evidence_typescript() -> String {
    let runtime_kinds = apxm_program::FactKind::all()
        .iter()
        .map(|kind| ts_string(kind.wire()))
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        r#"// AUTO-GENERATED from apxm.runtime-evidence.v1; DO NOT EDIT.
export const RUNTIME_FACT_KINDS = [{runtime_kinds}] as const;
export const ALL_FACT_KINDS = [...RUNTIME_FACT_KINDS, "LoopIterationCompleted"] as const;
export type RuntimeFactKind = (typeof RUNTIME_FACT_KINDS)[number];

export type RuntimeFact = {{
  readonly fact_id: string;
  readonly event_sequence: number;
  readonly fact_kind: RuntimeFactKind;
}};
export type NodeExecutionScope =
  | {{ readonly scope_kind: "non_loop" }}
  | {{ readonly scope_kind: "loop"; readonly region_occurrence_id: string; readonly static_region_id: string; readonly loop_memberships: ReadonlyArray<{{ readonly static_loop_id: string; readonly loop_occurrence_id: string }}> }};
export type NodeExecutionRecordedFact = {{
  readonly fact_id: string;
  readonly event_sequence: number;
  readonly fact_kind: "node_execution.recorded";
  readonly node_execution_id: string;
  readonly air_node_id: string;
  readonly parent_node_execution_id?: string;
  readonly execution_scope: NodeExecutionScope;
}};
export type LoopIterationCompletedFact = {{
  readonly fact_id: string;
  readonly event_sequence: number;
  readonly fact_kind: "LoopIterationCompleted";
  readonly static_loop_id: string;
  readonly loop_occurrence_id: string;
  readonly iteration_index: number;
  readonly program_invocation_id: string;
  readonly causal_node_execution_ids: readonly [string, ...string[]];
}};
export type Fact = RuntimeFact | NodeExecutionRecordedFact | LoopIterationCompletedFact;

const knownKinds = new Set<string>(ALL_FACT_KINDS);
function exact(value: Record<string, unknown>, required: readonly string[], optional: readonly string[] = []): void {{
  const allowed = new Set([...required, ...optional]);
  for (const key of required) if (!(key in value)) throw new Error(`missing fact field: ${{key}}`);
  for (const key of Object.keys(value)) if (!allowed.has(key)) throw new Error(`unknown fact field: ${{key}}`);
}}
export function decodeFact(input: unknown): Fact {{
  if (input === null || typeof input !== "object" || Array.isArray(input)) throw new Error("fact must be an object");
  const value = input as Record<string, unknown>;
  const kind = value.fact_kind;
  if (typeof kind !== "string" || !knownKinds.has(kind)) throw new Error(`unknown fact_kind: ${{String(kind)}}`);
  if (kind === "LoopIterationCompleted") {{
    exact(value, ["fact_id", "event_sequence", "fact_kind", "static_loop_id", "loop_occurrence_id", "iteration_index", "program_invocation_id", "causal_node_execution_ids"]);
    if (!Array.isArray(value.causal_node_execution_ids) || value.causal_node_execution_ids.length === 0) throw new Error("LoopIterationCompleted causality must be non-empty");
  }} else if (kind === "node_execution.recorded") {{
    exact(value, ["fact_id", "event_sequence", "fact_kind", "node_execution_id", "air_node_id", "execution_scope"], ["parent_node_execution_id"]);
    const scope = value.execution_scope as Record<string, unknown>;
    if (scope.scope_kind === "non_loop") exact(scope, ["scope_kind"]);
    else if (scope.scope_kind === "loop") {{
      exact(scope, ["scope_kind", "region_occurrence_id", "static_region_id", "loop_memberships"]);
      if (!Array.isArray(scope.loop_memberships) || scope.loop_memberships.length === 0) throw new Error("loop scope memberships must be non-empty");
    }} else throw new Error("unknown NodeExecution scope_kind");
  }} else exact(value, ["fact_id", "event_sequence", "fact_kind"], ["ownership_epoch", "instance_state", "invocation_state", "event_state", "model_outcome", "commit_sequence", "node_execution_id", "attempt_id", "region_occurrence_id", "static_region_id", "loop_memberships", "air_node_id", "parent_node_execution_id", "hook_execution_id", "hook_id", "hook_scope", "hook_phase", "context_transition_id", "context_before_ref", "context_after_ref", "effect_outcome_ref", "typed_error"]);
  return value as Fact;
}}
"#
    )
}

pub fn write_typescript_frontend_generated(output_dir: impl AsRef<Path>) -> Result<()> {
    let output_dir = output_dir.as_ref();
    fs::create_dir_all(output_dir)?;
    for (filename, content) in render_typescript_frontend_files() {
        fs::write(output_dir.join(filename), content)?;
    }
    Ok(())
}

pub fn render_generated_typescript() -> String {
    let mut buf = String::new();
    buf.push_str("// AUTO-GENERATED by apxm codegen typescript; DO NOT EDIT.\n\n");

    let ops = operation_specs();

    render_ts_field_spec(&mut buf);
    render_ts_op_spec(&mut buf);
    render_ts_dependency_types(&mut buf);
    render_ts_capability_groups(&mut buf);
    render_ts_operations(&mut buf, &ops);
    render_ts_categories(&mut buf, &ops);
    render_ts_attr_constants(&mut buf);
    render_ts_graph_metric_constants(&mut buf);
    render_ts_provider_types(&mut buf);
    render_ts_agents(&mut buf);

    buf
}

pub fn write_generated_typescript(output_path: impl AsRef<Path>) -> Result<()> {
    let output_path = output_path.as_ref();
    if let Some(parent) = output_path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_path, render_generated_typescript())?;
    Ok(())
}

fn render_ts_dependency_types(buf: &mut String) {
    buf.push_str("export enum DependencyType {\n");
    buf.push_str("  DATA = \"Data\",\n");
    buf.push_str("  CONTROL = \"Control\",\n");
    buf.push_str("  EFFECT = \"Effect\",\n");
    buf.push_str("}\n\n");
}

fn render_ts_capability_groups(buf: &mut String) {
    use apxm_core::constants::capabilities::groups;

    const CAPABILITY_GROUPS: &[(&str, &str)] = &[
        ("FILE", groups::FILE),
        ("FILE_READ", groups::FILE_READ),
        ("FILE_WRITE", groups::FILE_WRITE),
        ("HTTP", groups::HTTP),
        ("WEB", groups::WEB),
        ("SEARCH", groups::SEARCH),
        ("WEB_SEARCH", groups::WEB_SEARCH),
        ("SKILLS", groups::SKILLS),
        ("AUTHORING", groups::AUTHORING),
        ("TASK", groups::TASK),
        ("AGENT_MANAGEMENT", groups::AGENT_MANAGEMENT),
    ];

    buf.push_str("export enum ToolGroup {\n");
    for (ident, value) in CAPABILITY_GROUPS {
        buf.push_str(&format!("  {ident} = {},\n", ts_string(value)));
    }
    buf.push_str("}\n\n");
}

fn render_ts_field_spec(buf: &mut String) {
    buf.push_str("export type FieldSpec = {\n");
    buf.push_str("  readonly name: string;\n");
    buf.push_str("  readonly description: string;\n");
    buf.push_str("  readonly required: boolean;\n");
    buf.push_str("  readonly refType: string | null;\n");
    buf.push_str("};\n\n");
}

fn render_ts_op_spec(buf: &mut String) {
    buf.push_str("export type OpSpec = {\n");
    buf.push_str("  readonly op: string;\n");
    buf.push_str("  readonly name: string;\n");
    buf.push_str("  readonly category: OpCategory;\n");
    buf.push_str("  readonly description: string;\n");
    buf.push_str("  readonly longDescription: string;\n");
    buf.push_str("  readonly latency: string;\n");
    buf.push_str("  readonly fields: readonly FieldSpec[];\n");
    buf.push_str("  readonly producesOutput: boolean;\n");
    buf.push_str("  readonly needsSubmission: boolean;\n");
    buf.push_str("  readonly minInputs: number;\n");
    buf.push_str("  readonly exampleJson: string | null;\n");
    buf.push_str("};\n\n");
}

fn render_ts_operations(buf: &mut String, ops: &[FrontendOperationSpec]) {
    for spec in ops {
        let op = spec.op.to_string();
        let ident = op.to_ascii_uppercase();
        buf.push_str(&format!("export const {ident}: OpSpec = {{\n"));
        buf.push_str(&format!("  op: {},\n", ts_string(&op)));
        buf.push_str(&format!("  name: {},\n", ts_string(spec.name)));
        buf.push_str(&format!(
            "  category: {} as OpCategory,\n",
            ts_string(spec.category)
        ));
        buf.push_str(&format!(
            "  description: {},\n",
            ts_string(spec.description)
        ));
        buf.push_str(&format!(
            "  longDescription: {},\n",
            ts_string(spec.long_description)
        ));
        buf.push_str(&format!("  latency: {},\n", ts_string(spec.latency)));
        buf.push_str("  fields: [\n");
        for f in &spec.fields {
            buf.push_str(&format!(
                "    {{ name: {}, description: {}, required: {}, refType: {} }},\n",
                ts_string(f.name),
                ts_string(f.description),
                ts_bool(f.required),
                ts_optional_string(f.ref_type),
            ));
        }
        buf.push_str("  ],\n");
        buf.push_str(&format!(
            "  producesOutput: {},\n",
            ts_bool(spec.produces_output)
        ));
        buf.push_str(&format!(
            "  needsSubmission: {},\n",
            ts_bool(spec.needs_submission)
        ));
        buf.push_str(&format!("  minInputs: {},\n", spec.min_inputs));
        buf.push_str(&format!(
            "  exampleJson: {},\n",
            ts_optional_string(spec.example_json)
        ));
        buf.push_str("} as const;\n\n");
    }

    buf.push_str("export const ALL_OPERATIONS: readonly OpSpec[] = [\n");
    for spec in ops {
        buf.push_str(&format!(
            "  {},\n",
            spec.op.to_string().to_ascii_uppercase()
        ));
    }
    buf.push_str("] as const;\n\n");
}

fn render_ts_categories(buf: &mut String, ops: &[FrontendOperationSpec]) {
    let mut categories: Vec<&str> = ops.iter().map(|s| s.category).collect();
    categories.sort_unstable();
    categories.dedup();

    buf.push_str("export type OpCategory =\n");
    for (i, cat) in categories.iter().enumerate() {
        let sep = if i < categories.len() - 1 { "" } else { ";" };
        buf.push_str(&format!("  | {}{}\n", ts_string(cat), sep));
    }
    buf.push('\n');
}

fn render_ts_attr_constants(buf: &mut String) {
    buf.push_str("export const ATTR = {\n");
    for item in graph_attr_constants() {
        buf.push_str(&format!("  {}: {},\n", item.name, ts_string(item.value)));
    }
    buf.push_str("} as const;\n\n");
}

fn render_ts_graph_metric_constants(buf: &mut String) {
    buf.push_str("export const GRAPH_METRICS = {\n");
    for item in graph_metric_constants() {
        buf.push_str(&format!("  {}: {},\n", item.name, ts_string(item.value)));
    }
    buf.push_str("} as const;\n\n");
}

fn render_ts_provider_types(buf: &mut String) {
    let protocols = provider_protocols();
    buf.push_str("export type ProviderProtocol =\n");
    for (i, proto) in protocols.iter().enumerate() {
        let sep = if i < protocols.len() - 1 { "" } else { ";" };
        buf.push_str(&format!("  | {}{}\n", ts_string(proto), sep));
    }
    buf.push('\n');

    buf.push_str("export type ProviderSpec = {\n");
    buf.push_str("  readonly id: string;\n");
    buf.push_str("  readonly protocol: ProviderProtocol;\n");
    buf.push_str("  readonly defaultBaseUrl: string | null;\n");
    buf.push_str("  readonly requiresApiKey: boolean;\n");
    buf.push_str("  readonly apiKeyEnvVar: string | null;\n");
    buf.push_str("  readonly aliases: readonly string[];\n");
    buf.push_str("};\n\n");

    let providers = builtin_providers();
    buf.push_str("export const BUILTIN_PROVIDERS: readonly ProviderSpec[] = [\n");
    for p in &providers {
        buf.push_str("  {\n");
        buf.push_str(&format!("    id: {},\n", ts_string(p.id)));
        buf.push_str(&format!(
            "    protocol: {} as ProviderProtocol,\n",
            ts_string(p.protocol)
        ));
        buf.push_str(&format!(
            "    defaultBaseUrl: {},\n",
            ts_optional_string(p.default_base_url)
        ));
        buf.push_str(&format!(
            "    requiresApiKey: {},\n",
            ts_bool(p.requires_api_key)
        ));
        buf.push_str(&format!(
            "    apiKeyEnvVar: {},\n",
            ts_optional_string(p.api_key_env_var)
        ));
        buf.push_str(&format!(
            "    aliases: [{}],\n",
            p.aliases
                .iter()
                .map(|a| ts_string(a))
                .collect::<Vec<_>>()
                .join(", ")
        ));
        buf.push_str("  },\n");
    }
    buf.push_str("] as const;\n\n");
}

fn render_ts_agents(buf: &mut String) {
    buf.push_str("export type AgentTemplate = {\n");
    buf.push_str("  readonly name: string;\n");
    buf.push_str("  readonly command: string;\n");
    buf.push_str("  readonly description: string | null;\n");
    buf.push_str("  readonly routeCapabilities: readonly string[];\n");
    buf.push_str("  readonly source: string;\n");
    buf.push_str("  readonly defaultMode: string | null;\n");
    buf.push_str("  readonly defaultModel: string | null;\n");
    buf.push_str("};\n\n");

    let templates = agent_templates();
    buf.push_str("export const ALL_AGENTS: readonly AgentTemplate[] = [\n");
    for t in &templates {
        buf.push_str("  {\n");
        buf.push_str(&format!("    name: {},\n", ts_string(&t.name)));
        buf.push_str(&format!("    command: {},\n", ts_string(&t.command)));
        buf.push_str(&format!(
            "    description: {},\n",
            ts_optional_string(t.description.as_deref())
        ));
        buf.push_str("    routeCapabilities: [\n");
        for capability in &t.route_capabilities {
            buf.push_str(&format!("      {},\n", ts_string(capability)));
        }
        buf.push_str("    ],\n");
        buf.push_str(&format!("    source: {},\n", ts_string(&t.source)));
        buf.push_str(&format!(
            "    defaultMode: {},\n",
            ts_optional_string(t.default_mode.as_deref())
        ));
        buf.push_str(&format!(
            "    defaultModel: {},\n",
            ts_optional_string(t.default_model.as_deref())
        ));
        buf.push_str("  },\n");
    }
    buf.push_str("] as const;\n");
}

fn ts_string(value: &str) -> String {
    serde_json::to_string(value).expect("ts string literal")
}

fn constant_name(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect()
}

fn ts_optional_string(value: Option<&str>) -> String {
    match value {
        Some(v) => ts_string(v),
        None => "null".to_string(),
    }
}

fn ts_bool(value: bool) -> &'static str {
    if value { "true" } else { "false" }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generic_frontend_codegen_has_closed_contract_outputs() {
        let rendered = render_typescript_frontend_files();

        assert_eq!(
            rendered
                .iter()
                .map(|(filename, _)| *filename)
                .collect::<Vec<_>>(),
            vec!["frontend-contract.ts", "runtime-evidence.ts"]
        );
        let content = &rendered[0].1;
        for forbidden in [
            "GraphBuilder",
            "builder-ops",
            "workflow-draft",
            "REGISTER_CAPABILITY",
            "AUTONOMOUS",
        ] {
            assert!(!content.contains(forbidden), "{forbidden}");
        }
        for required in [
            "model.call",
            "capability.invoke",
            "program.new",
            "program.invoke",
            "await.event",
            "ais.loop",
            "parallel_join",
        ] {
            assert!(content.contains(required), "{required}");
        }
        let evidence = &rendered[1].1;
        for required in [
            "LoopIterationCompletedFact",
            "NodeExecutionRecordedFact",
            "decodeFact",
            "unknown fact_kind",
        ] {
            assert!(evidence.contains(required), "{required}");
        }
    }
}
